from pathlib import Path
import re
r=Path('dist')
header='''<header class="site-header"><a class="brand" href="index.html" aria-label="Panther Productions home"><span class="brand-symbol"><img src="assets/logo.png" alt=""></span><span>PANTHER<small>PRODUCTIONS</small></span></a><nav aria-label="Main navigation"><a href="work.html"><sup>01</sup> WORK</a><a href="studio.html"><sup>02</sup> STUDIO</a><a href="services.html"><sup>03</sup> SERVICES</a></nav><div class="header-actions"><a href="contact.html" class="talk">START A PROJECT <span>↗</span></a><button id="menu-open" aria-label="Open navigation" aria-controls="nav-dialog">☰</button></div></header><div class="page-progress" aria-hidden="true"><i></i></div>'''
menu='''<dialog class="nav-dialog" id="nav-dialog"><div class="menu-top"><span>PANTHER / DIRECTORY</span><button class="menu-close">CLOSE ✕</button></div><nav aria-label="Expanded navigation">'''+''.join('<a href="'+url+'"><sup>0'+str(i)+'</sup>'+name+'<span>↗</span></a>' for i,(url,name) in enumerate([('index.html','Home'),('work.html','Work'),('studio.html','Studio'),('services.html','Services'),('contact.html','Contact')]))+'''</nav><span class="menu-note">SILENT BY NATURE. FEARLESS BY INSTINCT.</span></dialog>'''
footer='''<footer class="site-footer"><div class="footer-top"><span>EVERY GREAT STORY<br>STARTS WITH AN INSTINCT.</span><a href="contact.html">LET’S MAKE A SCENE ↗</a></div><a class="footer-word" href="index.html" aria-label="Panther home">PANTHER<span>®</span></a><div class="footer-bottom"><span>© <span id="year"></span> PANTHER PRODUCTIONS</span><div class="footer-links"><a href="work.html">WORK</a><a href="studio.html">STUDIO</a><a href="services.html">SERVICES</a><a href="contact.html">CONTACT</a></div><a href="#top">BACK TO TOP ↑</a></div></footer>'''
closing='''<section class="closing-cta"><span class="section-code">YOUR NEXT FRAME</span><h2>DON’T BLEND IN.<br><em>LEAVE A MARK.</em></h2><a href="contact.html" class="contact-button">START A PROJECT ↗</a></section>'''
for p in r.glob('*.html'):
 s=p.read_text().replace('<body class="','<body id="top" class="')
 s=re.sub(r'<header>.*?</header>',header,s,flags=re.S);s=re.sub(r'<footer>.*?</footer>',footer,s,flags=re.S)
 s=s.replace('<link rel="stylesheet" href="style.css">','<link rel="stylesheet" href="style.css"><link rel="stylesheet" href="obsidian.css">')
 s=s.replace('</body>',menu+'<script src="shell.js"></script></body>')
 if p.name=='index.html':
  s=s.replace('<div class="seq-face" aria-hidden="true"><img src="assets/panther-face.jpg" alt=""><i class="seq-lid left"></i><i class="seq-lid right"></i></div>','<div class="seq-face sculpture-object" aria-hidden="true"><img src="assets/obsidian-panther.jpg" alt=""></div><span class="hero-outline" aria-hidden="true">PANTHER</span>')
  s=s.replace('PANTHER PRODUCTIONS / INDEPENDENT CREATIVE STUDIO','INDEPENDENT MINDS. UNTAMED IMAGINATION.').replace('FOLLOW<br>THE <em>INSTINCT.</em>','RAW INSTINCT.<br><em>PURE IMPACT.</em>').replace('Some stories ask for attention.<br>Ours hunt for it.','A production house for stories<br>that refuse to blend in.')
  s=re.sub(r'<section class="manifesto">.*?</section>','''<section class="manifesto word-reveal"><div class="section-code">P.01 / THE MINDSET</div><h2>WE SEE THE<br>WORLD DIFFERENTLY.<br><span>THEN WE SHOOT IT.</span></h2><div class="manifesto-bottom"><p>A camera is only the beginning. We bring instinct, intention and craft to every step — from the first idea to the final frame.</p><a class="text-link" href="studio.html">MEET THE STUDIO ↗</a></div><div class="slash-signature" aria-hidden="true"><i></i><i></i><i></i></div></section>''',s,flags=re.S)
 if p.name=='work.html':s=re.sub(r'<section class="page-lead panther-lead">.*?</section>','''<section class="portfolio-lead"><div class="section-code">P.01 / THE VISUAL ARCHIVE</div><h1>FRAME<br><em>OF MIND.</em><sup>03</sup></h1><div class="lead-bottom"><p>Stories told in light, texture and motion.</p><span>ILLUSTRATIVE CONCEPT STUDIES</span></div></section>''',s,flags=re.S)
 if p.name=='studio.html':
  main='''<section class="studio-intro"><img class="studio-sculpture" src="assets/obsidian-panther.jpg" alt="Sculptural black Panther with crimson rim light"><div class="section-code">P.02 / THE STUDIO</div><h1>QUIET<br>CONFIDENCE.<br><em>WILD VISION.</em></h1><p>Panther Productions.<br>A point of view. A way of making.</p></section><section class="studio-essay word-reveal"><span class="section-code">WHAT DRIVES THE FRAME</span><div><h2>INSTINCT IS<br>WHERE IT STARTS.<br><em>CRAFT IS HOW<br>IT HAPPENS.</em></h2><p>We see production as one connected creative journey. An idea becomes a visual language. A shoot gives it life. An edit finds its rhythm.</p><p>Every stage deserves the same attention. Every choice should move the story forward.</p><a class="text-link" href="services.html">EXPLORE OUR DISCIPLINES ↗</a></div></section><section class="studio-film"><img src="assets/set.jpg" alt="Behind the scenes on a cinematic film set"><span>FROM FIRST SPARK TO FINAL FRAME.</span><button id="open-film">INSIDE THE FRAME <b>↗</b></button></section><section class="principles"><div class="section-code">THE PANTHER APPROACH</div><div>'''+''.join('<article><span>'+code+'</span><h3>'+title+'</h3><p>'+body+'</p></article>' for code,title,body in [('01 / OBSERVE','Find the unexpected.','Look closer. Question the obvious. Find the idea that feels worth pursuing.'),('02 / CREATE','Make every move count.','Give each shot a purpose, each detail a place and each project a clear direction.'),('03 / REFINE','Know when it’s right.','Shape the image, the rhythm and the finish until the story feels complete.')])+'''</div></section>'''+closing
  s=re.sub(r'<main>.*?</main>','<main>'+main+'</main>',s,flags=re.S)
 if p.name=='contact.html':
  form=re.search(r'<form id="brief-form">.*?</form>',s,re.S).group()
  main='''<section class="contact-intro"><span class="section-code">P.04 / OPEN CHANNEL</span><h1>LET’S MAKE<br><em>A SCENE.</em><span>↗</span></h1><p>Big idea. Small spark. Something in between.<br>Tell us where you want to take it.</p></section><section class="contact-workspace"><aside><span class="section-code">YOUR NEXT FRAME</span><h2>THE BRIEF<br>BEGINS HERE.</h2><p>Build your project brief, download it and share it with the studio.</p><div class="contact-eye" aria-hidden="true"><img src="assets/panther-face.jpg" alt=""></div></aside><div class="brief" id="brief">'''+form+'''</div></section>'''
  s=re.sub(r'<main>.*?</main>','<main>'+main+'</main>',s,flags=re.S)
 if p.name.startswith('service-'):s=re.sub(r'<div class="panther-portrait" aria-hidden="true">.*?</div>','',s,flags=re.S)
 s=re.sub(r'<section class="page-cta panther-cta">.*?</section>',closing,s,flags=re.S)
 p.write_text(s)
